  // HALL OF FAME: Kommentatorin Jessica (387 Sätze, Block 41–49) – spricht nur in der Halle, der Kommentator nur im Stadion
  CLIPS.push(...[{"id": "h1_00", "block": 41, "nr": 1, "dauer": 2.47, "text": "Herzlich willkommen in der Hall of Fame!"}, {"id": "h1_01", "block": 41, "nr": 2, "dauer": 2.14, "text": "Hallo und guten Tag aus der Halle!"}, {"id": "h1_02", "block": 41, "nr": 3, "dauer": 2.47, "text": "Die Halle ist bereit, die Teams auch."}, {"id": "h1_03", "block": 41, "nr": 4, "dauer": 3.79, "text": "Fünf gegen fünf, auf engstem Raum – das wird schnell!"}, {"id": "h1_04", "block": 41, "nr": 5, "dauer": 2.09, "text": "Hallenfußball, meine Damen und Herren!"}, {"id": "h1_05", "block": 41, "nr": 6, "dauer": 1.2, "text": "Der Ball rollt!"}, {"id": "h1_06", "block": 41, "nr": 7, "dauer": 0.91, "text": "Anstoß!"}, {"id": "h1_07", "block": 41, "nr": 8, "dauer": 1.32, "text": "Und los geht's!"}, {"id": "h1_08", "block": 41, "nr": 9, "dauer": 1.27, "text": "Gleich ist Anpfiff."}, {"id": "h1_09", "block": 41, "nr": 10, "dauer": 1.78, "text": "Hier ist richtig was los!"}, {"id": "h1_10", "block": 41, "nr": 11, "dauer": 2.14, "text": "Was für eine Stimmung in der Halle!"}, {"id": "h1_11", "block": 41, "nr": 12, "dauer": 2.04, "text": "Hier wird keine Sekunde verschenkt."}, {"id": "h1_12", "block": 41, "nr": 13, "dauer": 1.87, "text": "Tempo, Tempo, Tempo!"}, {"id": "h1_13", "block": 41, "nr": 14, "dauer": 1.58, "text": "Das geht hin und her!"}, {"id": "h1_14", "block": 41, "nr": 15, "dauer": 2.09, "text": "Beide Teams suchen den Weg nach vorne."}, {"id": "h1_15", "block": 41, "nr": 16, "dauer": 1.54, "text": "Ruhiger Spielaufbau."}, {"id": "h1_16", "block": 41, "nr": 17, "dauer": 2.04, "text": "Kurze Pässe, schnelle Wege."}, {"id": "h1_17", "block": 41, "nr": 18, "dauer": 1.49, "text": "Sauber kombiniert!"}, {"id": "h1_18", "block": 41, "nr": 19, "dauer": 1.44, "text": "Schöner Doppelpass!"}, {"id": "h1_19", "block": 41, "nr": 20, "dauer": 1.27, "text": "Der Ball läuft gut."}, {"id": "h1_20", "block": 41, "nr": 21, "dauer": 1.46, "text": "Jetzt wird es gefährlich!"}, {"id": "h1_21", "block": 41, "nr": 22, "dauer": 1.03, "text": "Da ist Platz!"}, {"id": "h1_22", "block": 41, "nr": 23, "dauer": 1.37, "text": "Gute Ballkontrolle."}, {"id": "h1_23", "block": 41, "nr": 24, "dauer": 1.32, "text": "Und weiter geht's."}, {"id": "h1_24", "block": 41, "nr": 25, "dauer": 1.27, "text": "Das Spiel ist offen."}, {"id": "h1_25", "block": 41, "nr": 26, "dauer": 1.49, "text": "Hier ist alles drin!"}, {"id": "h1_26", "block": 41, "nr": 27, "dauer": 1.58, "text": "Die Halle bebt!"}, {"id": "h1_27", "block": 41, "nr": 28, "dauer": 1.32, "text": "Schnell umgeschaltet!"}, {"id": "h1_28", "block": 41, "nr": 29, "dauer": 0.74, "text": "Konter!"}, {"id": "h1_29", "block": 41, "nr": 30, "dauer": 1.22, "text": "Jetzt aber schnell!"}, {"id": "h1_30", "block": 41, "nr": 31, "dauer": 2.93, "text": "Was für eine Atmosphäre hier unter dem Hallendach!"}, {"id": "h1_31", "block": 41, "nr": 32, "dauer": 2.81, "text": "Die Zuschauer sind von Anfang an voll dabei."}, {"id": "h1_32", "block": 41, "nr": 33, "dauer": 2.21, "text": "Beide Mannschaften wirken hellwach."}, {"id": "h1_33", "block": 41, "nr": 34, "dauer": 2.62, "text": "Das wird ein echtes Hallenspektakel!"}, {"id": "h1_34", "block": 41, "nr": 35, "dauer": 2.28, "text": "Hier zählt Technik mehr als Kraft."}, {"id": "h1_35", "block": 41, "nr": 36, "dauer": 2.76, "text": "Ein Ballkontakt, und schon ist man vor dem Tor."}, {"id": "h2_00", "block": 42, "nr": 1, "dauer": 0.79, "text": "Tor!"}, {"id": "h2_01", "block": 42, "nr": 2, "dauer": 0.91, "text": "Toooor!"}, {"id": "h2_02", "block": 42, "nr": 3, "dauer": 1.7, "text": "Und da ist das Tor!"}, {"id": "h2_03", "block": 42, "nr": 4, "dauer": 1.32, "text": "Drin ist das Ding!"}, {"id": "h2_04", "block": 42, "nr": 5, "dauer": 1.56, "text": "Was für ein Treffer!"}, {"id": "h2_05", "block": 42, "nr": 6, "dauer": 1.13, "text": "Unhaltbar!"}, {"id": "h2_06", "block": 42, "nr": 7, "dauer": 1.08, "text": "Der sitzt!"}, {"id": "h2_07", "block": 42, "nr": 8, "dauer": 1.54, "text": "Eiskalt verwandelt!"}, {"id": "h2_08", "block": 42, "nr": 9, "dauer": 1.51, "text": "Mitten in den Winkel!"}, {"id": "h2_09", "block": 42, "nr": 10, "dauer": 1.27, "text": "Flach ins Eck!"}, {"id": "h2_10", "block": 42, "nr": 11, "dauer": 1.66, "text": "Was für ein Abschluss!"}, {"id": "h2_11", "block": 42, "nr": 12, "dauer": 1.68, "text": "Das ist ein Traumtor!"}, {"id": "h2_12", "block": 42, "nr": 13, "dauer": 1.37, "text": "Ganz stark gemacht!"}, {"id": "h2_13", "block": 42, "nr": 14, "dauer": 1.68, "text": "Und das Netz zappelt!"}, {"id": "h2_14", "block": 42, "nr": 15, "dauer": 1.08, "text": "Die Führung!"}, {"id": "h2_15", "block": 42, "nr": 16, "dauer": 1.32, "text": "Da ist die Führung!"}, {"id": "h2_16", "block": 42, "nr": 17, "dauer": 1.25, "text": "Jetzt führen sie!"}, {"id": "h2_17", "block": 42, "nr": 18, "dauer": 1.44, "text": "Das ist der Ausgleich!"}, {"id": "h2_18", "block": 42, "nr": 19, "dauer": 2.33, "text": "Ausgleich! Alles wieder offen!"}, {"id": "h2_19", "block": 42, "nr": 20, "dauer": 1.49, "text": "Der Anschlusstreffer!"}, {"id": "h2_20", "block": 42, "nr": 21, "dauer": 1.85, "text": "Nur noch ein Tor Rückstand!"}, {"id": "h2_21", "block": 42, "nr": 22, "dauer": 1.68, "text": "Sie bauen die Führung aus!"}, {"id": "h2_22", "block": 42, "nr": 23, "dauer": 1.85, "text": "Das könnte die Entscheidung sein!"}, {"id": "h2_23", "block": 42, "nr": 24, "dauer": 1.78, "text": "Das ist die Vorentscheidung!"}, {"id": "h2_24", "block": 42, "nr": 25, "dauer": 1.92, "text": "Was für eine Aufholjagd!"}, {"id": "h2_25", "block": 42, "nr": 26, "dauer": 1.15, "text": "Sie kommen zurück!"}, {"id": "h2_26", "block": 42, "nr": 27, "dauer": 1.92, "text": "Das Comeback ist perfekt!"}, {"id": "h2_27", "block": 42, "nr": 28, "dauer": 1.56, "text": "Die Halle steht kopf!"}, {"id": "h2_28", "block": 42, "nr": 29, "dauer": 1.13, "text": "Wahnsinn!"}, {"id": "h2_29", "block": 42, "nr": 30, "dauer": 1.49, "text": "Was für ein Moment!"}, {"id": "h2_30", "block": 42, "nr": 31, "dauer": 2.62, "text": "Unten links, keine Chance für den Torwart!"}, {"id": "h2_31", "block": 42, "nr": 32, "dauer": 2.18, "text": "Oben rechts, genau in den Knick!"}, {"id": "h2_32", "block": 42, "nr": 33, "dauer": 1.75, "text": "Mit links, eiskalt!"}, {"id": "h2_33", "block": 42, "nr": 34, "dauer": 1.85, "text": "Mit rechts, wuchtig!"}, {"id": "h2_34", "block": 42, "nr": 35, "dauer": 1.51, "text": "Was für ein Hammer!"}, {"id": "h2_35", "block": 42, "nr": 36, "dauer": 1.82, "text": "Der Torwart war schon geschlagen."}, {"id": "h2_36", "block": 42, "nr": 37, "dauer": 1.68, "text": "Ganz abgezockt gemacht."}, {"id": "h2_37", "block": 42, "nr": 38, "dauer": 2.4, "text": "Das ist Hallenfußball vom Feinsten!"}, {"id": "h2_38", "block": 42, "nr": 39, "dauer": 1.85, "text": "Durch die Beine, frech!"}, {"id": "h2_39", "block": 42, "nr": 40, "dauer": 1.75, "text": "Der Ball zappelt im Netz!"}, {"id": "h2_40", "block": 42, "nr": 41, "dauer": 2.16, "text": "Den Treffer hat sich das Team verdient."}, {"id": "h2_41", "block": 42, "nr": 42, "dauer": 1.7, "text": "Und schon wieder klingelt es!"}, {"id": "h2_42", "block": 42, "nr": 43, "dauer": 1.8, "text": "Ein Tor wie gemalt!"}, {"id": "h3_00", "block": 43, "nr": 1, "dauer": 0.77, "text": "Schuss!"}, {"id": "h3_01", "block": 43, "nr": 2, "dauer": 1.1, "text": "Da zieht er ab!"}, {"id": "h3_02", "block": 43, "nr": 3, "dauer": 0.94, "text": "Abschluss!"}, {"id": "h3_03", "block": 43, "nr": 4, "dauer": 1.32, "text": "Aus der Distanz!"}, {"id": "h3_04", "block": 43, "nr": 5, "dauer": 1.13, "text": "Weitschuss!"}, {"id": "h3_05", "block": 43, "nr": 6, "dauer": 0.86, "text": "Volley!"}, {"id": "h3_06", "block": 43, "nr": 7, "dauer": 1.68, "text": "Was für ein Volley!"}, {"id": "h3_07", "block": 43, "nr": 8, "dauer": 1.54, "text": "Direkt abgezogen!"}, {"id": "h3_08", "block": 43, "nr": 9, "dauer": 1.2, "text": "Knapp vorbei!"}, {"id": "h3_09", "block": 43, "nr": 10, "dauer": 0.96, "text": "Ganz knapp!"}, {"id": "h3_10", "block": 43, "nr": 11, "dauer": 1.99, "text": "Haarscharf am Pfosten vorbei!"}, {"id": "h3_11", "block": 43, "nr": 12, "dauer": 0.84, "text": "Pfosten!"}, {"id": "h3_12", "block": 43, "nr": 13, "dauer": 1.18, "text": "An den Pfosten!"}, {"id": "h3_13", "block": 43, "nr": 14, "dauer": 0.84, "text": "Latte!"}, {"id": "h3_14", "block": 43, "nr": 15, "dauer": 1.56, "text": "Die Latte zittert!"}, {"id": "h3_15", "block": 43, "nr": 16, "dauer": 0.82, "text": "Drüber!"}, {"id": "h3_16", "block": 43, "nr": 17, "dauer": 1.27, "text": "Deutlich drüber!"}, {"id": "h3_17", "block": 43, "nr": 18, "dauer": 1.22, "text": "Das war zu hoch."}, {"id": "h3_18", "block": 43, "nr": 19, "dauer": 1.1, "text": "Zu ungenau."}, {"id": "h3_19", "block": 43, "nr": 20, "dauer": 1.42, "text": "Da fehlte nicht viel!"}, {"id": "h3_20", "block": 43, "nr": 21, "dauer": 1.44, "text": "Die große Chance!"}, {"id": "h3_21", "block": 43, "nr": 22, "dauer": 1.39, "text": "Die muss er machen!"}, {"id": "h3_22", "block": 43, "nr": 23, "dauer": 1.25, "text": "Riesenchance!"}, {"id": "h3_23", "block": 43, "nr": 24, "dauer": 1.2, "text": "Und vergeben!"}, {"id": "h3_24", "block": 43, "nr": 25, "dauer": 1.82, "text": "Das war die Gelegenheit!"}, {"id": "h3_25", "block": 43, "nr": 26, "dauer": 1.97, "text": "Gut gezielt, aber daneben."}, {"id": "h3_26", "block": 43, "nr": 27, "dauer": 2.09, "text": "Der Ball will einfach nicht rein!"}, {"id": "h3_27", "block": 43, "nr": 28, "dauer": 1.44, "text": "Schon wieder knapp!"}, {"id": "h3_28", "block": 43, "nr": 29, "dauer": 1.2, "text": "Mutiger Versuch!"}, {"id": "h3_29", "block": 43, "nr": 30, "dauer": 1.68, "text": "Einfach mal draufgehalten!"}, {"id": "h3_30", "block": 43, "nr": 31, "dauer": 1.92, "text": "Er versucht es aus spitzem Winkel."}, {"id": "h3_31", "block": 43, "nr": 32, "dauer": 1.15, "text": "Mit der Pike!"}, {"id": "h3_32", "block": 43, "nr": 33, "dauer": 2.04, "text": "Da fehlten nur Zentimeter!"}, {"id": "h3_33", "block": 43, "nr": 34, "dauer": 2.02, "text": "Der Ball streicht am Tor vorbei."}, {"id": "h3_34", "block": 43, "nr": 35, "dauer": 1.7, "text": "Knapp am Winkel vorbei!"}, {"id": "h3_35", "block": 43, "nr": 36, "dauer": 1.32, "text": "Das hätte gepasst!"}, {"id": "h3_36", "block": 43, "nr": 37, "dauer": 2.88, "text": "Die Zuschauer haben den Torschrei schon auf den Lippen."}, {"id": "h3_37", "block": 43, "nr": 38, "dauer": 1.9, "text": "Ein Raunen geht durch die Halle!"}, {"id": "h3_38", "block": 43, "nr": 39, "dauer": 2.45, "text": "Schade, das war fast perfekt!"}, {"id": "h3_39", "block": 43, "nr": 40, "dauer": 1.58, "text": "Er hat zu viel Rücklage."}, {"id": "h3_40", "block": 43, "nr": 41, "dauer": 1.44, "text": "Den muss er flach halten."}, {"id": "h3_41", "block": 43, "nr": 42, "dauer": 2.23, "text": "Gute Idee, schwache Ausführung."}, {"id": "h3_42", "block": 43, "nr": 43, "dauer": 1.44, "text": "Er sucht das lange Eck."}, {"id": "h3_43", "block": 43, "nr": 44, "dauer": 1.51, "text": "Er zielt aufs kurze Eck."}, {"id": "h3_44", "block": 43, "nr": 45, "dauer": 1.25, "text": "Mit Vollspann!"}, {"id": "h3_45", "block": 43, "nr": 46, "dauer": 1.61, "text": "Mit Gefühl gelupft!"}, {"id": "h3_46", "block": 43, "nr": 47, "dauer": 1.42, "text": "Der Ball dreht sich weg."}, {"id": "h3_47", "block": 43, "nr": 48, "dauer": 1.58, "text": "Das war ein Warnschuss!"}, {"id": "h4_00", "block": 44, "nr": 1, "dauer": 1.1, "text": "Gehalten!"}, {"id": "h4_01", "block": 44, "nr": 2, "dauer": 1.66, "text": "Was für eine Parade!"}, {"id": "h4_02", "block": 44, "nr": 3, "dauer": 1.46, "text": "Glänzend pariert!"}, {"id": "h4_03", "block": 44, "nr": 4, "dauer": 1.32, "text": "Der Torwart ist da!"}, {"id": "h4_04", "block": 44, "nr": 5, "dauer": 1.39, "text": "Klasse Reflex!"}, {"id": "h4_05", "block": 44, "nr": 6, "dauer": 1.87, "text": "Mit den Fingerspitzen!"}, {"id": "h4_06", "block": 44, "nr": 7, "dauer": 1.39, "text": "Stark gehalten!"}, {"id": "h4_07", "block": 44, "nr": 8, "dauer": 1.75, "text": "Der hält einfach alles!"}, {"id": "h4_08", "block": 44, "nr": 9, "dauer": 1.2, "text": "Sicher gefangen."}, {"id": "h4_09", "block": 44, "nr": 10, "dauer": 1.18, "text": "Den hat er sicher."}, {"id": "h4_10", "block": 44, "nr": 11, "dauer": 1.58, "text": "Kein Problem für den Keeper."}, {"id": "h4_11", "block": 44, "nr": 12, "dauer": 1.01, "text": "Abgewehrt!"}, {"id": "h4_12", "block": 44, "nr": 13, "dauer": 1.39, "text": "Mit dem Fuß geklärt!"}, {"id": "h4_13", "block": 44, "nr": 14, "dauer": 1.9, "text": "Was für eine Rettungstat!"}, {"id": "h4_14", "block": 44, "nr": 15, "dauer": 1.56, "text": "Der Torwart rettet!"}, {"id": "h4_15", "block": 44, "nr": 16, "dauer": 1.8, "text": "Weltklasse vom Torwart!"}, {"id": "h4_16", "block": 44, "nr": 17, "dauer": 1.49, "text": "Hellwach, der Keeper!"}, {"id": "h4_17", "block": 44, "nr": 18, "dauer": 1.2, "text": "Er wirft schnell ab!"}, {"id": "h4_18", "block": 44, "nr": 19, "dauer": 1.32, "text": "Schneller Abwurf!"}, {"id": "h4_19", "block": 44, "nr": 20, "dauer": 1.97, "text": "Der Torwart leitet den Konter ein!"}, {"id": "h4_20", "block": 44, "nr": 21, "dauer": 1.27, "text": "Weit nach vorne!"}, {"id": "h4_21", "block": 44, "nr": 22, "dauer": 2.09, "text": "Der Keeper hält sein Team im Spiel!"}, {"id": "h4_22", "block": 44, "nr": 23, "dauer": 1.3, "text": "Riesentat!"}, {"id": "h4_23", "block": 44, "nr": 24, "dauer": 2.59, "text": "Unglaublich, wie hat er den gehalten?"}, {"id": "h4_24", "block": 44, "nr": 25, "dauer": 1.61, "text": "Da war der Torwart schneller!"}, {"id": "h4_25", "block": 44, "nr": 26, "dauer": 1.25, "text": "Gut rausgelaufen!"}, {"id": "h4_26", "block": 44, "nr": 27, "dauer": 1.42, "text": "Mutig rausgekommen!"}, {"id": "h4_27", "block": 44, "nr": 28, "dauer": 1.97, "text": "Der Torwart klärt die Situation."}, {"id": "h4_28", "block": 44, "nr": 29, "dauer": 1.32, "text": "Sicherer Rückhalt."}, {"id": "h4_29", "block": 44, "nr": 30, "dauer": 1.99, "text": "Bärenstark, dieser Torwart!"}, {"id": "h4_30", "block": 44, "nr": 31, "dauer": 1.56, "text": "Er macht sich ganz lang!"}, {"id": "h4_31", "block": 44, "nr": 32, "dauer": 1.73, "text": "Mit einer Hand gerettet!"}, {"id": "h4_32", "block": 44, "nr": 33, "dauer": 1.63, "text": "Der Keeper liest den Schuss."}, {"id": "h4_33", "block": 44, "nr": 34, "dauer": 1.73, "text": "Gute Stellung, ganz sicher."}, {"id": "h4_34", "block": 44, "nr": 35, "dauer": 1.73, "text": "Da hat er den Winkel verkürzt."}, {"id": "h4_35", "block": 44, "nr": 36, "dauer": 1.58, "text": "Der Torwart fliegt!"}, {"id": "h4_36", "block": 44, "nr": 37, "dauer": 1.68, "text": "Was für ein Hechtsprung!"}, {"id": "h4_37", "block": 44, "nr": 38, "dauer": 2.02, "text": "Er bleibt lange stehen und pariert."}, {"id": "h4_38", "block": 44, "nr": 39, "dauer": 2.06, "text": "Der Keeper ist heute in Topform."}, {"id": "h4_39", "block": 44, "nr": 40, "dauer": 2.21, "text": "Ein Torwart wie eine Wand!"}, {"id": "h4_40", "block": 44, "nr": 41, "dauer": 1.7, "text": "Er fischt den Ball aus dem Eck!"}, {"id": "h4_41", "block": 44, "nr": 42, "dauer": 1.37, "text": "Tolle Fußabwehr!"}, {"id": "h5_00", "block": 45, "nr": 1, "dauer": 1.13, "text": "An die Bande!"}, {"id": "h5_01", "block": 45, "nr": 2, "dauer": 2.14, "text": "Der Ball springt von der Bande zurück!"}, {"id": "h5_02", "block": 45, "nr": 3, "dauer": 1.58, "text": "Über die Bande gespielt!"}, {"id": "h5_03", "block": 45, "nr": 4, "dauer": 1.54, "text": "Doppelpass mit der Bande!"}, {"id": "h5_04", "block": 45, "nr": 5, "dauer": 1.75, "text": "Clever die Bande genutzt!"}, {"id": "h5_05", "block": 45, "nr": 6, "dauer": 1.39, "text": "Die Bande spielt mit!"}, {"id": "h5_06", "block": 45, "nr": 7, "dauer": 1.56, "text": "Abpraller von der Bande!"}, {"id": "h5_07", "block": 45, "nr": 8, "dauer": 2.88, "text": "Kein Aus in der Halle – es geht sofort weiter!"}, {"id": "h5_08", "block": 45, "nr": 9, "dauer": 1.63, "text": "Der Ball bleibt im Spiel!"}, {"id": "h5_09", "block": 45, "nr": 10, "dauer": 1.7, "text": "Mit Wucht an die Bande!"}, {"id": "h5_10", "block": 45, "nr": 11, "dauer": 2.06, "text": "In der Halle zählt jeder Meter."}, {"id": "h5_11", "block": 45, "nr": 12, "dauer": 2.06, "text": "Wenig Platz, viel Tempo!"}, {"id": "h5_12", "block": 45, "nr": 13, "dauer": 1.97, "text": "Enger Raum, schnelle Füße!"}, {"id": "h5_13", "block": 45, "nr": 14, "dauer": 1.56, "text": "Typisch Hallenfußball!"}, {"id": "h5_14", "block": 45, "nr": 15, "dauer": 1.73, "text": "So geht Hallenfußball!"}, {"id": "h5_15", "block": 45, "nr": 16, "dauer": 0.77, "text": "Wechsel!"}, {"id": "h5_16", "block": 45, "nr": 17, "dauer": 1.34, "text": "Fliegender Wechsel!"}, {"id": "h5_17", "block": 45, "nr": 18, "dauer": 1.63, "text": "Frische Kräfte kommen rein!"}, {"id": "h5_18", "block": 45, "nr": 19, "dauer": 1.61, "text": "Neuer Mann auf dem Feld!"}, {"id": "h5_19", "block": 45, "nr": 20, "dauer": 1.08, "text": "Durchgewechselt!"}, {"id": "h5_20", "block": 45, "nr": 21, "dauer": 1.68, "text": "Die Bank kommt zum Einsatz."}, {"id": "h5_21", "block": 45, "nr": 22, "dauer": 1.87, "text": "Kurze Pause zum Durchatmen."}, {"id": "h5_22", "block": 45, "nr": 23, "dauer": 1.2, "text": "Gleich geht es weiter."}, {"id": "h5_23", "block": 45, "nr": 24, "dauer": 1.66, "text": "Wieder rein ins Getümmel!"}, {"id": "h5_24", "block": 45, "nr": 25, "dauer": 1.49, "text": "Die Kräfte lassen nach."}, {"id": "h5_25", "block": 45, "nr": 26, "dauer": 1.73, "text": "Das kostet Kraft hier drin!"}, {"id": "h5_26", "block": 45, "nr": 27, "dauer": 1.58, "text": "Die Halle ist heiß!"}, {"id": "h5_27", "block": 45, "nr": 28, "dauer": 1.73, "text": "Hier wird nichts verschenkt!"}, {"id": "h5_28", "block": 45, "nr": 29, "dauer": 1.61, "text": "Volle Konzentration!"}, {"id": "h5_29", "block": 45, "nr": 30, "dauer": 1.3, "text": "Pressing in der Halle!"}, {"id": "h5_30", "block": 45, "nr": 31, "dauer": 2.35, "text": "Der Ball prallt unberechenbar zurück."}, {"id": "h5_31", "block": 45, "nr": 32, "dauer": 2.4, "text": "Die Bande als zusätzlicher Mitspieler!"}, {"id": "h5_32", "block": 45, "nr": 33, "dauer": 3.26, "text": "Mit Wucht abgeprallt – und gleich wieder gefährlich!"}, {"id": "h5_33", "block": 45, "nr": 34, "dauer": 1.7, "text": "Dort an der Bande wird es eng."}, {"id": "h5_34", "block": 45, "nr": 35, "dauer": 2.59, "text": "Zwei Spieler kämpfen an der Bande um den Ball."}, {"id": "h5_35", "block": 45, "nr": 36, "dauer": 2.28, "text": "Er nutzt den Abpraller clever aus."}, {"id": "h6_00", "block": 46, "nr": 1, "dauer": 1.01, "text": "Zweikampf!"}, {"id": "h6_01", "block": 46, "nr": 2, "dauer": 1.37, "text": "Hart, aber fair."}, {"id": "h6_02", "block": 46, "nr": 3, "dauer": 1.2, "text": "Ball erobert!"}, {"id": "h6_03", "block": 46, "nr": 4, "dauer": 1.73, "text": "Starke Balleroberung!"}, {"id": "h6_04", "block": 46, "nr": 5, "dauer": 1.51, "text": "Gut dazwischengegangen!"}, {"id": "h6_05", "block": 46, "nr": 6, "dauer": 0.89, "text": "Grätsche!"}, {"id": "h6_06", "block": 46, "nr": 7, "dauer": 1.42, "text": "Saubere Grätsche!"}, {"id": "h6_07", "block": 46, "nr": 8, "dauer": 0.96, "text": "Abgefangen!"}, {"id": "h6_08", "block": 46, "nr": 9, "dauer": 0.86, "text": "Geklärt!"}, {"id": "h6_09", "block": 46, "nr": 10, "dauer": 1.15, "text": "Weggeschlagen!"}, {"id": "h6_10", "block": 46, "nr": 11, "dauer": 0.84, "text": "Foul!"}, {"id": "h6_11", "block": 46, "nr": 12, "dauer": 1.42, "text": "Das war ein Foul."}, {"id": "h6_12", "block": 46, "nr": 13, "dauer": 1.3, "text": "Da pfeift der Schiri."}, {"id": "h6_13", "block": 46, "nr": 14, "dauer": 0.98, "text": "Freistoß."}, {"id": "h6_14", "block": 46, "nr": 15, "dauer": 1.42, "text": "Zu ungestüm."}, {"id": "h6_15", "block": 46, "nr": 16, "dauer": 1.9, "text": "Den hat er von hinten umgemäht."}, {"id": "h6_16", "block": 46, "nr": 17, "dauer": 1.13, "text": "Das gibt Gelb."}, {"id": "h6_17", "block": 46, "nr": 18, "dauer": 1.1, "text": "Gelbe Karte!"}, {"id": "h6_18", "block": 46, "nr": 19, "dauer": 0.96, "text": "Verwarnung."}, {"id": "h6_19", "block": 46, "nr": 20, "dauer": 0.79, "text": "Rot!"}, {"id": "h6_20", "block": 46, "nr": 21, "dauer": 1.13, "text": "Platzverweis!"}, {"id": "h6_21", "block": 46, "nr": 22, "dauer": 1.39, "text": "Das war zu viel!"}, {"id": "h6_22", "block": 46, "nr": 23, "dauer": 1.68, "text": "Der Schiedsrichter greift durch."}, {"id": "h6_23", "block": 46, "nr": 24, "dauer": 1.66, "text": "Die Gemüter erhitzen sich."}, {"id": "h6_24", "block": 46, "nr": 25, "dauer": 2.02, "text": "Jetzt nur nicht die Nerven verlieren!"}, {"id": "h6_25", "block": 46, "nr": 26, "dauer": 1.15, "text": "Ruhig bleiben!"}, {"id": "h6_26", "block": 46, "nr": 27, "dauer": 1.54, "text": "Er beschwert sich beim Schiri."}, {"id": "h6_27", "block": 46, "nr": 28, "dauer": 1.08, "text": "Weiterspielen!"}, {"id": "h6_28", "block": 46, "nr": 29, "dauer": 0.86, "text": "Vorteil!"}, {"id": "h6_29", "block": 46, "nr": 30, "dauer": 1.46, "text": "Der Schiri lässt laufen."}, {"id": "h6_30", "block": 46, "nr": 31, "dauer": 1.87, "text": "Er geht beherzt in den Zweikampf."}, {"id": "h6_31", "block": 46, "nr": 32, "dauer": 1.22, "text": "Der Ball ist weg!"}, {"id": "h6_32", "block": 46, "nr": 33, "dauer": 1.08, "text": "Gut gestört!"}, {"id": "h6_33", "block": 46, "nr": 34, "dauer": 1.49, "text": "Er läuft ihn einfach ab."}, {"id": "h6_34", "block": 46, "nr": 35, "dauer": 1.82, "text": "Mit Körpereinsatz behauptet."}, {"id": "h6_35", "block": 46, "nr": 36, "dauer": 1.85, "text": "Da wird nicht zurückgezogen!"}, {"id": "h6_36", "block": 46, "nr": 37, "dauer": 1.97, "text": "Der Schiedsrichter zeigt auf den Punkt."}, {"id": "h6_37", "block": 46, "nr": 38, "dauer": 1.44, "text": "Das war unglücklich."}, {"id": "h6_38", "block": 46, "nr": 39, "dauer": 1.37, "text": "Ein taktisches Foul."}, {"id": "h6_39", "block": 46, "nr": 40, "dauer": 1.73, "text": "Er hat nur den Mann getroffen."}, {"id": "h6_40", "block": 46, "nr": 41, "dauer": 1.73, "text": "Klare Sache, Foul."}, {"id": "h6_41", "block": 46, "nr": 42, "dauer": 1.92, "text": "Er hat Glück, dass es nicht mehr gab."}, {"id": "h6_42", "block": 46, "nr": 43, "dauer": 1.82, "text": "Das war knapp an der Grenze."}, {"id": "h6_43", "block": 46, "nr": 44, "dauer": 1.82, "text": "Der Schiri beruhigt die Spieler."}, {"id": "h6_44", "block": 46, "nr": 45, "dauer": 2.21, "text": "Hier wird mit offenem Visier gespielt."}, {"id": "h6_45", "block": 46, "nr": 46, "dauer": 1.63, "text": "Er steht sofort wieder auf."}, {"id": "h6_46", "block": 46, "nr": 47, "dauer": 1.49, "text": "Kurze Behandlungspause."}, {"id": "h7_00", "block": 47, "nr": 1, "dauer": 1.25, "text": "Null zu null."}, {"id": "h7_01", "block": 47, "nr": 2, "dauer": 1.27, "text": "Noch keine Tore."}, {"id": "h7_02", "block": 47, "nr": 3, "dauer": 1.01, "text": "Eins zu null."}, {"id": "h7_03", "block": 47, "nr": 4, "dauer": 1.2, "text": "Eins zu eins."}, {"id": "h7_04", "block": 47, "nr": 5, "dauer": 1.13, "text": "Zwei zu null."}, {"id": "h7_05", "block": 47, "nr": 6, "dauer": 1.2, "text": "Zwei zu eins."}, {"id": "h7_06", "block": 47, "nr": 7, "dauer": 1.25, "text": "Zwei zu zwei."}, {"id": "h7_07", "block": 47, "nr": 8, "dauer": 1.15, "text": "Drei zu null."}, {"id": "h7_08", "block": 47, "nr": 9, "dauer": 1.15, "text": "Drei zu eins."}, {"id": "h7_09", "block": 47, "nr": 10, "dauer": 1.15, "text": "Drei zu zwei."}, {"id": "h7_10", "block": 47, "nr": 11, "dauer": 1.22, "text": "Drei zu drei."}, {"id": "h7_11", "block": 47, "nr": 12, "dauer": 1.18, "text": "Vier zu null."}, {"id": "h7_12", "block": 47, "nr": 13, "dauer": 1.15, "text": "Vier zu eins."}, {"id": "h7_13", "block": 47, "nr": 14, "dauer": 1.25, "text": "Vier zu zwei."}, {"id": "h7_14", "block": 47, "nr": 15, "dauer": 2.14, "text": "Was für ein Torfestival!"}, {"id": "h7_15", "block": 47, "nr": 16, "dauer": 0.91, "text": "Halbzeit!"}, {"id": "h7_16", "block": 47, "nr": 17, "dauer": 1.39, "text": "Halbzeit in der Halle."}, {"id": "h7_17", "block": 47, "nr": 18, "dauer": 2.3, "text": "Kurze Pause, dann Seitenwechsel."}, {"id": "h7_18", "block": 47, "nr": 19, "dauer": 1.78, "text": "Die zweite Hälfte läuft!"}, {"id": "h7_19", "block": 47, "nr": 20, "dauer": 1.13, "text": "Schlussphase!"}, {"id": "h7_20", "block": 47, "nr": 21, "dauer": 1.56, "text": "Noch eine halbe Minute!"}, {"id": "h7_21", "block": 47, "nr": 22, "dauer": 1.58, "text": "Die letzten Sekunden!"}, {"id": "h7_22", "block": 47, "nr": 23, "dauer": 2.09, "text": "Jetzt zählt jede Sekunde!"}, {"id": "h7_23", "block": 47, "nr": 24, "dauer": 1.18, "text": "Gleich ist Schluss!"}, {"id": "h7_24", "block": 47, "nr": 25, "dauer": 0.86, "text": "Abpfiff!"}, {"id": "h7_25", "block": 47, "nr": 26, "dauer": 1.49, "text": "Das Spiel ist aus!"}, {"id": "h7_26", "block": 47, "nr": 27, "dauer": 2.66, "text": "Sieg! Was für eine Leistung!"}, {"id": "h7_27", "block": 47, "nr": 28, "dauer": 1.44, "text": "Leider verloren."}, {"id": "h7_28", "block": 47, "nr": 29, "dauer": 1.01, "text": "Unentschieden!"}, {"id": "h7_29", "block": 47, "nr": 30, "dauer": 1.56, "text": "Punkteteilung in der Halle."}, {"id": "h7_30", "block": 47, "nr": 31, "dauer": 1.13, "text": "Fünf zu null."}, {"id": "h7_31", "block": 47, "nr": 32, "dauer": 1.15, "text": "Fünf zu eins."}, {"id": "h7_32", "block": 47, "nr": 33, "dauer": 1.25, "text": "Fünf zu zwei."}, {"id": "h7_33", "block": 47, "nr": 34, "dauer": 1.37, "text": "Es steht unentschieden."}, {"id": "h7_34", "block": 47, "nr": 35, "dauer": 1.75, "text": "Hier ist noch nichts entschieden."}, {"id": "h7_35", "block": 47, "nr": 36, "dauer": 1.39, "text": "Die Führung wackelt."}, {"id": "h7_36", "block": 47, "nr": 37, "dauer": 1.8, "text": "Jetzt nur nicht nachlassen!"}, {"id": "h7_37", "block": 47, "nr": 38, "dauer": 1.1, "text": "Die Uhr tickt."}, {"id": "h7_38", "block": 47, "nr": 39, "dauer": 1.49, "text": "Noch zehn Sekunden!"}, {"id": "h7_39", "block": 47, "nr": 40, "dauer": 1.58, "text": "Fünf, vier, drei …"}, {"id": "h7_40", "block": 47, "nr": 41, "dauer": 2.74, "text": "Die letzte Aktion des Spiels!"}, {"id": "h7_41", "block": 47, "nr": 42, "dauer": 1.66, "text": "Der Schlusspfiff ertönt!"}, {"id": "h7_42", "block": 47, "nr": 43, "dauer": 1.7, "text": "Feierabend in der Halle!"}, {"id": "h7_43", "block": 47, "nr": 44, "dauer": 1.63, "text": "Ein verdienter Sieg!"}, {"id": "h7_44", "block": 47, "nr": 45, "dauer": 1.85, "text": "Eine bittere Niederlage."}, {"id": "h7_45", "block": 47, "nr": 46, "dauer": 1.61, "text": "Am Ende reicht es nicht."}, {"id": "h7_46", "block": 47, "nr": 47, "dauer": 1.99, "text": "Ein Spiel zum Mitreißen!"}, {"id": "h7_47", "block": 47, "nr": 48, "dauer": 2.14, "text": "Wir sagen danke für dieses Spiel!"}, {"id": "h7_48", "block": 47, "nr": 49, "dauer": 1.8, "text": "Kopf hoch, weiter geht's!"}, {"id": "h8_00", "block": 48, "nr": 1, "dauer": 2.35, "text": "Willkommen zum Hall of Fame Cup!"}, {"id": "h8_01", "block": 48, "nr": 2, "dauer": 2.04, "text": "Acht Teams, ein Pokal!"}, {"id": "h8_02", "block": 48, "nr": 3, "dauer": 1.82, "text": "Die Gruppenphase beginnt!"}, {"id": "h8_03", "block": 48, "nr": 4, "dauer": 1.39, "text": "Erstes Gruppenspiel!"}, {"id": "h8_04", "block": 48, "nr": 5, "dauer": 1.49, "text": "Zweites Gruppenspiel!"}, {"id": "h8_05", "block": 48, "nr": 6, "dauer": 3.17, "text": "Letztes Gruppenspiel – jetzt geht es um alles!"}, {"id": "h8_06", "block": 48, "nr": 7, "dauer": 1.08, "text": "Drei Punkte!"}, {"id": "h8_07", "block": 48, "nr": 8, "dauer": 0.89, "text": "Ein Punkt."}, {"id": "h8_08", "block": 48, "nr": 9, "dauer": 1.13, "text": "Keine Punkte."}, {"id": "h8_09", "block": 48, "nr": 10, "dauer": 1.25, "text": "Tabellenführer!"}, {"id": "h8_10", "block": 48, "nr": 11, "dauer": 1.78, "text": "Das reicht fürs Halbfinale!"}, {"id": "h8_11", "block": 48, "nr": 12, "dauer": 1.18, "text": "Halbfinale!"}, {"id": "h8_12", "block": 48, "nr": 13, "dauer": 1.85, "text": "Wir stehen im Halbfinale!"}, {"id": "h8_13", "block": 48, "nr": 14, "dauer": 1.8, "text": "Das Halbfinale beginnt!"}, {"id": "h8_14", "block": 48, "nr": 15, "dauer": 1.1, "text": "Finale!"}, {"id": "h8_15", "block": 48, "nr": 16, "dauer": 1.15, "text": "Das Finale!"}, {"id": "h8_16", "block": 48, "nr": 17, "dauer": 1.66, "text": "Wir stehen im Finale!"}, {"id": "h8_17", "block": 48, "nr": 18, "dauer": 1.78, "text": "Jetzt geht es um den Pokal!"}, {"id": "h8_18", "block": 48, "nr": 19, "dauer": 1.75, "text": "Ein Spiel noch zum Titel!"}, {"id": "h8_19", "block": 48, "nr": 20, "dauer": 1.15, "text": "Turniersieg!"}, {"id": "h8_20", "block": 48, "nr": 21, "dauer": 2.4, "text": "Der Hall of Fame Cup gehört euch!"}, {"id": "h8_21", "block": 48, "nr": 22, "dauer": 1.7, "text": "Die Champions der Halle!"}, {"id": "h8_22", "block": 48, "nr": 23, "dauer": 2.38, "text": "Pokal! Was für ein Turnier!"}, {"id": "h8_23", "block": 48, "nr": 24, "dauer": 2.11, "text": "Unglaublich, der Titel!"}, {"id": "h8_24", "block": 48, "nr": 25, "dauer": 1.06, "text": "Ausgeschieden."}, {"id": "h8_25", "block": 48, "nr": 26, "dauer": 1.8, "text": "Leider ist das Turnier vorbei."}, {"id": "h8_26", "block": 48, "nr": 27, "dauer": 1.32, "text": "Das war's in der Gruppe."}, {"id": "h8_27", "block": 48, "nr": 28, "dauer": 1.7, "text": "Im Halbfinale gescheitert."}, {"id": "h8_28", "block": 48, "nr": 29, "dauer": 2.78, "text": "Im Finale verloren – trotzdem stark!"}, {"id": "h8_29", "block": 48, "nr": 30, "dauer": 2.14, "text": "Nächstes Mal holt ihr den Pokal!"}, {"id": "h8_30", "block": 48, "nr": 31, "dauer": 1.7, "text": "Die Gruppe ist ausgelost!"}, {"id": "h8_31", "block": 48, "nr": 32, "dauer": 1.32, "text": "Schwere Gruppe!"}, {"id": "h8_32", "block": 48, "nr": 33, "dauer": 1.18, "text": "Machbare Gruppe!"}, {"id": "h8_33", "block": 48, "nr": 34, "dauer": 2.66, "text": "Ein Sieg, und das Halbfinale ist sicher!"}, {"id": "h8_34", "block": 48, "nr": 35, "dauer": 1.61, "text": "Jetzt brauchen wir Punkte!"}, {"id": "h8_35", "block": 48, "nr": 36, "dauer": 1.7, "text": "Die Tabelle ist ganz eng."}, {"id": "h8_36", "block": 48, "nr": 37, "dauer": 1.61, "text": "Platz eins in der Gruppe!"}, {"id": "h8_37", "block": 48, "nr": 38, "dauer": 1.92, "text": "Gruppenzweiter, das reicht!"}, {"id": "h8_38", "block": 48, "nr": 39, "dauer": 2.06, "text": "Nur die besten zwei kommen weiter."}, {"id": "h8_39", "block": 48, "nr": 40, "dauer": 1.87, "text": "Jetzt beginnt die K.-o.-Phase!"}, {"id": "h8_40", "block": 48, "nr": 41, "dauer": 1.56, "text": "Alles oder nichts!"}, {"id": "h9_00", "block": 49, "nr": 1, "dauer": 1.44, "text": "Elfmeterschießen!"}, {"id": "h9_01", "block": 49, "nr": 2, "dauer": 2.33, "text": "Jetzt entscheidet das Elfmeterschießen!"}, {"id": "h9_02", "block": 49, "nr": 3, "dauer": 2.16, "text": "Nerven aus Stahl sind gefragt!"}, {"id": "h9_03", "block": 49, "nr": 4, "dauer": 2.04, "text": "Der Schütze legt sich den Ball zurecht."}, {"id": "h9_04", "block": 49, "nr": 5, "dauer": 1.01, "text": "Er läuft an …"}, {"id": "h9_05", "block": 49, "nr": 6, "dauer": 0.91, "text": "Anlauf …"}, {"id": "h9_06", "block": 49, "nr": 7, "dauer": 0.72, "text": "Und …"}, {"id": "h9_07", "block": 49, "nr": 8, "dauer": 0.72, "text": "Drin!"}, {"id": "h9_08", "block": 49, "nr": 9, "dauer": 1.42, "text": "Sicher verwandelt!"}, {"id": "h9_09", "block": 49, "nr": 10, "dauer": 0.96, "text": "Eiskalt!"}, {"id": "h9_10", "block": 49, "nr": 11, "dauer": 1.25, "text": "Ins linke Eck!"}, {"id": "h9_11", "block": 49, "nr": 12, "dauer": 1.18, "text": "Ins rechte Eck!"}, {"id": "h9_12", "block": 49, "nr": 13, "dauer": 0.96, "text": "Gehalten!"}, {"id": "h9_13", "block": 49, "nr": 14, "dauer": 1.49, "text": "Der Torwart pariert!"}, {"id": "h9_14", "block": 49, "nr": 15, "dauer": 0.94, "text": "Vorbei!"}, {"id": "h9_15", "block": 49, "nr": 16, "dauer": 1.13, "text": "Verschossen!"}, {"id": "h9_16", "block": 49, "nr": 17, "dauer": 1.18, "text": "Über das Tor!"}, {"id": "h9_17", "block": 49, "nr": 18, "dauer": 1.22, "text": "An den Pfosten!"}, {"id": "h9_18", "block": 49, "nr": 19, "dauer": 1.25, "text": "Der Druck steigt!"}, {"id": "h9_19", "block": 49, "nr": 20, "dauer": 1.39, "text": "Wer behält die Nerven?"}, {"id": "h9_20", "block": 49, "nr": 21, "dauer": 1.39, "text": "Alles ausgeglichen!"}, {"id": "h9_21", "block": 49, "nr": 22, "dauer": 1.49, "text": "Jetzt muss er treffen!"}, {"id": "h9_22", "block": 49, "nr": 23, "dauer": 1.2, "text": "Sudden Death!"}, {"id": "h9_23", "block": 49, "nr": 24, "dauer": 1.97, "text": "Der nächste Treffer kann entscheiden!"}, {"id": "h9_24", "block": 49, "nr": 25, "dauer": 1.46, "text": "Das ist die Entscheidung!"}, {"id": "h9_25", "block": 49, "nr": 26, "dauer": 0.96, "text": "Entschieden!"}, {"id": "h9_26", "block": 49, "nr": 27, "dauer": 1.75, "text": "Sieg im Elfmeterschießen!"}, {"id": "h9_27", "block": 49, "nr": 28, "dauer": 1.99, "text": "Im Elfmeterschießen verloren."}, {"id": "h9_28", "block": 49, "nr": 29, "dauer": 1.42, "text": "Was für ein Krimi!"}, {"id": "h9_29", "block": 49, "nr": 30, "dauer": 1.44, "text": "Die Halle tobt!"}, {"id": "h9_30", "block": 49, "nr": 31, "dauer": 1.92, "text": "Er schaut dem Torwart in die Augen."}, {"id": "h9_31", "block": 49, "nr": 32, "dauer": 2.45, "text": "Der Torwart springt auf der Linie hin und her."}, {"id": "h9_32", "block": 49, "nr": 33, "dauer": 1.18, "text": "Kurzer Anlauf …"}, {"id": "h9_33", "block": 49, "nr": 34, "dauer": 1.27, "text": "Langer Anlauf …"}, {"id": "h9_34", "block": 49, "nr": 35, "dauer": 1.58, "text": "Mit Wucht in die Mitte!"}, {"id": "h9_35", "block": 49, "nr": 36, "dauer": 1.06, "text": "Hoch ins Eck!"}, {"id": "h9_36", "block": 49, "nr": 37, "dauer": 1.42, "text": "Flach unten rein!"}, {"id": "h9_37", "block": 49, "nr": 38, "dauer": 2.14, "text": "Der Torwart war in der richtigen Ecke!"}, {"id": "h9_38", "block": 49, "nr": 39, "dauer": 1.73, "text": "Falsche Ecke vom Torwart!"}, {"id": "h9_39", "block": 49, "nr": 40, "dauer": 1.49, "text": "Ganz cool geschoben!"}, {"id": "h9_40", "block": 49, "nr": 41, "dauer": 1.9, "text": "Der Ball knallt an die Latte!"}, {"id": "h9_41", "block": 49, "nr": 42, "dauer": 1.75, "text": "Die Nerven haben versagt."}, {"id": "h9_42", "block": 49, "nr": 43, "dauer": 2.06, "text": "Was für ein Druck auf den Schultern!"}, {"id": "h9_43", "block": 49, "nr": 44, "dauer": 1.85, "text": "Die Halle hält den Atem an."}, {"id": "h9_44", "block": 49, "nr": 45, "dauer": 2.16, "text": "Mucksmäuschenstill ist es hier."}]);
